sql.where:
r.record_status = 1
AND r.user_id = #{form.userId}
AND r.template_id = #{form.templateId}
AND r.task_id = #{form.taskId}
AND r.record_status = #{form.recordStatus}
AND r.submit_time >= #{form.startDate}
AND r.submit_time <= #{form.endDate}

mapper.select:
SELECT r.user_id AS userId, u.real_name AS userName, u.emp_no AS userEmpNo, u.dept_name AS userDept, COUNT(*) AS submitCount, COUNT(DISTINCT COALESCE(t.dispatch_id, t.id)) AS periodCount, MAX(r.submit_time) AS lastSubmitTime FROM flow_form_record r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN flow_task t ON r.task_id = t.id LEFT JOIN flow_task_dispatch d ON COALESCE(t.dispatch_id, t.id) = d.id WHERE r.record_status = 1 AND d.task_id = #{taskId}
AND (u.real_name LIKE CONCAT('%', #{name}, '%') OR u.emp_no LIKE CONCAT('%', #{name}, '%'))
GROUP BY r.user_id, u.real_name, u.emp_no, u.dept_name ORDER BY submitCount DESC, r.user_id ASC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ( SELECT r.user_id FROM flow_form_record r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN flow_task t ON r.task_id = t.id LEFT JOIN flow_task_dispatch d ON COALESCE(t.dispatch_id, t.id) = d.id WHERE r.record_status = 1 AND d.task_id = #{taskId}
AND (u.real_name LIKE CONCAT('%', #{name}, '%') OR u.emp_no LIKE CONCAT('%', #{name}, '%'))
GROUP BY r.user_id ) p

SELECT DATE_FORMAT(submit_time, '%Y-%m') AS date, COUNT(*) AS count FROM flow_form_record WHERE record_status = 1
AND DATE(submit_time) >= #{startDate}
AND submit_time >= '2026-09-01'
AND DATE(submit_time) <= #{endDate}
GROUP BY DATE_FORMAT(submit_time, '%Y-%m')
SELECT CONCAT(YEAR(submit_time), '-Q', QUARTER(submit_time)) AS date, COUNT(*) AS count FROM flow_form_record WHERE record_status = 1
AND DATE(submit_time) >= #{startDate}
AND submit_time >= '2026-09-01'
AND DATE(submit_time) <= #{endDate}
GROUP BY CONCAT(YEAR(submit_time), '-Q', QUARTER(submit_time))
SELECT DATE_FORMAT(submit_time, '%Y') AS date, COUNT(*) AS count FROM flow_form_record WHERE record_status = 1
AND DATE(submit_time) >= #{startDate}
AND submit_time >= '2026-09-01'
AND DATE(submit_time) <= #{endDate}
GROUP BY DATE_FORMAT(submit_time, '%Y')
SELECT DATE_FORMAT(submit_time, '%Y-%m-%d') AS date, COUNT(*) AS count FROM flow_form_record WHERE record_status = 1
AND DATE(submit_time) >= #{startDate}
AND submit_time >= '2026-09-01'
AND DATE(submit_time) <= #{endDate}
GROUP BY DATE_FORMAT(submit_time, '%Y-%m-%d')
ORDER BY date
